export const STORAGE_KEY='quiet-list-v1';
const id=()=>crypto.randomUUID();
export function initial(){return {version:1,lists:[{id:id(),name:'Everything on my mind',color:'lavender',tasks:[]},{id:id(),name:'Home & me',color:'sage',tasks:[]},{id:id(),name:'Ideas for later',color:'peach',tasks:[]}]};}
export function validate(data){if(!data||data.version!==1||!Array.isArray(data.lists)||!data.lists.length||data.lists.length>100)throw Error('This is not a supported Quiet List backup.');let ids=new Set();for(const list of data.lists){if(typeof list.id!=='string'||ids.has(list.id)||typeof list.name!=='string'||!list.name.trim()||list.name.length>80||!Array.isArray(list.tasks)||list.tasks.length>10000)throw Error('Invalid list in backup.');ids.add(list.id);for(const task of list.tasks){if(typeof task.id!=='string'||ids.has(task.id)||typeof task.text!=='string'||!task.text.trim()||task.text.length>2000||typeof task.done!=='boolean')throw Error('Invalid task in backup.');ids.add(task.id);}}return data;}
export function createList(state,name,color='lavender'){name=name.trim();if(!name||name.length>80)throw Error('Give your list a name, up to 80 characters.');if(state.lists.length>=100)throw Error('This prototype supports 100 lists.');const list={id:id(),name,color,tasks:[]};state.lists.push(list);return list;}
export function addTask(list,text){text=text.trim();if(!text||text.length>2000)throw Error('Write a thought, up to 2,000 characters.');if(list.tasks.length>=10000)throw Error('This list is full.');const task={id:id(),text,done:false};list.tasks.push(task);return task;}
export function updateTask(list,taskId,patch){const task=list.tasks.find(t=>t.id===taskId);if(!task)throw Error('Task not found.');if('text' in patch){const text=patch.text.trim();if(!text||text.length>2000)throw Error('Write a thought, up to 2,000 characters.');task.text=text;}if('done' in patch)task.done=!!patch.done;return task;}
